saveOutputCode:
async function(result,args,action,direction,frame,start,visual_status="candidate_visual_review_pending",attempt=1){
const root="D:/work/image/qdao_original_roster_v14_hd/action-remake-20261001/characters/02_fire_talisman_boy";
const id=`${action}-${direction}-${String(frame).padStart(2,"0")}-20261003${attempt>1?"-attempt"+attempt:""}`;
const match=result.output_hint.match(/as (C:\\[^\n]+?\.png) by default/);
if(!match)throw Error("No actual source path in tool output");
const nativeFile=`work/${action==="hit"?"hit":"run-"+direction}/${direction}-${String(frame).padStart(2,"0")}-20261003${attempt>1?"-attempt"+attempt:""}-native.png`;
const record={schemaVersion:1,action,direction,frame,status:"generated_exported_sequence_pending",file:nativeFile,submittedAt:start,timezone:"America/New_York",tool:"image_gen.imagegen",route:"builtin",configSnapshot:load("hitRecord").configSnapshot,submittedParameters:{...args,model:null,quality:null},actualModel:null,actualQuality:null,unverifiedReason:"宿主管理，工具未开放model/quality选择器，返回未披露实际模型/质量；实际值未确认。",prompt:"prompts/"+id+".txt",references:args.referenced_image_paths.map(path=>({path,sha256:(load("refSha")||{})[path]||null,viewed:true})),evidence:{sourcePath:match[1],resultKeys:Object.keys(result),output_hint:result.output_hint},export:{file:`frames/${action}/${direction}/${String(frame).padStart(2,"0")}.png`},visual_status,generatedAtMeaning:"记录持久化时间（America/New_York），不是服务器披露的实际生成时间"};
if(args.referenced_image_paths[0].includes("/work/"))record.editTarget={file:args.referenced_image_paths[0],sourceRecord:(load("sourceRecordMap")||{})[args.referenced_image_paths[0]]||null,sourceSha256:(load("refSha")||{})[args.referenced_image_paths[0]]||null};
const recPath=root+"/records/"+id+".generation.json";
await tools.apply_patch("*** Begin Patch\n*** Add File: "+recPath+"\n"+JSON.stringify(record,null,2).split("\n").map(x=>"+"+x).join("\n")+"\n*** End Patch");
const out=await tools.exec_command({cmd:"& '"+root+"/tools/hit_production_save.ps1' -RecordPath '"+recPath+"'",max_output_tokens:1200});
if(out.exit_code!==0)throw Error("Local export failed "+out.output);
const meta=JSON.parse(out.output);const sha=load("refSha")||{};sha[root+"/"+nativeFile]=meta.native_sha256;store("refSha",sha);const src=load("sourceRecordMap")||{};src[root+"/"+nativeFile]="records/"+id+".generation.json";store("sourceRecordMap",src);text(meta);return record;
}

